from functools import singledispatchmethod
import threading
import time
import logging
import random
from queue import Queue
from pyrlang import Node
from pyrlang.process import Process  # pylint: disable=no-name-in-module
from term import Atom
from term.reference import Reference
from robotbackgroundlogger import BackgroundLogger
from taf.ue.cus.utils import Atoms, CommandStartedMsg, EventMsg, CommandStatusMsg

PYTHON_NODE = 'pycus@127.0.0.1'
EXECUTOR_NODE_NAME = 'executor'
EXECUTOR_NODE_HOST = '127.0.0.1'
PYTHON_REGISTERED_NAME = 'pycus'
ATOMIZED_EXECUTOR_REGISTERED_NAME = Atom('executor_4iex')
COOKIE = "hacker"

ATOMS = Atoms()
command_started_msg = CommandStartedMsg()
event_msg = EventMsg()
command_status_msg = CommandStatusMsg()
bg_logger = BackgroundLogger()

class EventReceiver(Process):
    def __init__(self, store_events):
        super().__init__()
        self._store_events = store_events
        self._events = []

    def handle_one_inbox_message(self, msg):
        if self._store_events and msg[0] == ATOMS.event:
            # (Atom('event'), b'21.11:45:14.263| Connection Manager: All SECTORs and TGRs disconnected')
            self._events.append(msg[-1].decode('utf-8'))

    def get_stored_events(self):
        """Get stored events"""
        stored_events = self._events
        self._reset_stored_events()
        return stored_events

    def set_store_events(self, store_events):
        """Set whether to store events"""
        self._store_events = store_events

    def _reset_stored_events(self):
        """Reset stored events"""
        self._events = []


class Receiver(Process):
    def __init__(self, node, queue, timeout, counter, reference):
        Process.__init__(self)
        self._until = None
        self._node = node
        self._queue = queue #
        self._acc = []
        self._counter = counter
        self._reference = reference #
        self._start_timer(timeout) #

    def handle_one_inbox_message(self, msg):
        """Handle one inbox message"""
        msg_type = {ATOMS.command_started: command_started_msg,
                    ATOMS.event: event_msg,
                    ATOMS.command_status: command_status_msg}[msg[0]]
        self._dispatch_msg(msg_type, msg)

    @singledispatchmethod
    def _dispatch_msg(self, msg_type, _):
        raise NotImplementedError("No handler for message type: {}".format(msg_type))

    @_dispatch_msg.register(CommandStartedMsg)
    def _(self, _msg_type, msg):
        if msg[1] == self._reference and msg[2] == self._counter:
            # (Atom('command_started'), Ref<1,0,4,4213814978>@pycus, 0, 1800000)
            self._until += self._until + 1

    @_dispatch_msg.register(EventMsg)
    def _(self, _msg_type, msg):
        # (Atom('event'), b'25.16:08:31.421| Connection Manager: Connecting to SECTOR-2@1 192.168.200.1:8005')
        self._acc.append(msg[-1].decode('utf-8'))
        self._until += self._until + 1

    @_dispatch_msg.register(CommandStatusMsg)
    def _(self, _msg_type, msg):
        if msg[1] == self._reference and msg[2] == self._counter:
            # (Atom('command_status'), Ref<1,0,4,3988923723>@pycus, 0, Atom('ok')
            # (Atom('command_status'), Ref<1,0,0,4235510861>@pycus, 0, (Atom('error'), (Atom('code'), 1)))
            self._queue.put((msg[-1], self._acc)) # (status, [events])
            self._acc = []
            self._until = None
            del self

    def _reset(self, queue, timeout, reference):
        """Reset receiver"""
        self._queue = queue
        self._acc = []
        self._reference = reference
        self._start_timer(timeout)

    def _start_timer(self, timeout):
        """Start timer"""
        self._until = time.time() + timeout
        self._node.get_loop().call_later(1, self._check_timeout)

    def _check_timeout(self):
        """Check timeout"""
        if self._until is not None:
            if time.time() > self._until:
                self._queue.put(ATOMS.timeout)
                self._acc = []
                self._until = None
                del self
            else:
                self._node.get_loop().call_later(self._until - time.time(), self._check_timeout)

class CusExecutor:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            with cls._lock:
                if not cls._instance:
                    cls._instance = super(CusExecutor, cls).__new__(cls)
        return cls._instance

    def __init__(self, executor_host=EXECUTOR_NODE_HOST, store_events=False):
        if not hasattr(self, "_initialized"):
            self._executor_node = '{}@{}'.format(EXECUTOR_NODE_NAME, executor_host)
            self._atomized_executor_node = Atom('{}@{}'.format(EXECUTOR_NODE_NAME, executor_host))
            self._node = None
            self._event_receiver = None
            self._cmd_receiver = None
            self._timeout = 5
            self._counter = 0
            logging.getLogger('pyrlang.node').disabled = True
            if not CusExecutor._is_dry_run():
                self._start_node(store_events)
            self._initialized = True

    def _start_node(self, store_events):
        self._node = Node(node_name=PYTHON_NODE, cookie=COOKIE)

        # Hack to prevent "Task exception was never retrieved" error caused by missing process keys
        # in the Node's process dictionary during link operations.
        cached_link = Node.link
        async def safe_link(*args, **kwargs):
            try:
                cached_link(*args, **kwargs)
            except Exception:
                pass
        self._node.link = safe_link

        daemon_thread = threading.Thread(target=self._node.run)
        daemon_thread.daemon = True
        daemon_thread.start()
        self._event_receiver = EventReceiver(store_events=store_events)
        self._node.get_loop().create_task(self._send_event_sink())  # to keep connection alive

    def __enter__(self):
        return self

    def __exit__(self, _type, _value, _traceback):
        # self._node.get_loop().call_soon(lambda future: future.set_result(True), self._node._Node__completed_future)
        self._node.node_db.deactivate(self._node)

    def _set_new_cmd_receiver(self, results_queue, counter, reference):
        self._cmd_receiver = Receiver(self._node, results_queue, self._timeout, counter, reference)

    def __getattr__(self, command):
        if command == "_initialized":
            raise AttributeError(f"'{self.__class__.__name__}' object has no attribute '{command}'")
        command = command.replace('_', ' ').strip()
        def cmd_func(*args, **kwargs):
            if args or kwargs:
                raise TypeError(f"Executor command '{command}' provided as function takes no arguments")
            else:
                return self.execute_command(command)
        return cmd_func

    def set_store_events(self, store_events):
        """Set whether to store events"""
        self._event_receiver.set_store_events(store_events)

    def get_stored_events(self):
        """Get stored events"""
        return self._event_receiver.get_stored_events()

    def execute_command(self, cmd):
        """
        Execute a command on the Executor.
        If the command times out on the first attempt, the method retries the execution after handling
        the timeout scenario.

        Args:
            cmd (str): The command to be executed on the executor node.

        Returns:
            Sequence[strings]: The result of the command execution as a sequence of strings.
        """
        result = self._execute_command(cmd, 1)
        if result == ATOMS.timeout:
            self._node.unregister_dist_node(self._executor_node)
            self._node.get_loop().create_task(self._send_event_sink())
            result = self._execute_command(cmd, 2)
        return result

    def _execute_command(self, cmd, attempt):
        results_queue = Queue()
        reference = self._get_reference()

        self._node.get_loop().call_soon(self._set_new_cmd_receiver, results_queue, self._counter, reference)
        self._node.get_loop().create_task(self._send_cmd(cmd, self._counter, reference))

        self._counter += 1

        result = results_queue.get(timeout=None)
        # TODO: add structural pattern matching when Python 3.10 becomes default in UTE
        if result[0] == ATOMS.ok: # ((ATOMS.ok), events)
            return result[1]
        elif result[0][0] == ATOMS.error:  # ((Atom('error'), (Atom('code'), 1)), events)
            error_code_str = ''
            events = "\n".join(event for event in result[1])
            if isinstance(result[0][1], tuple) and result[0][1][0] == ATOMS.code:
                error_code_str = f' with code {result[0][1][1]}'
            raise ExecutorErrorException(f"Command failed{error_code_str}: {events}")
        elif result == ATOMS.timeout and attempt == 1:
            return ATOMS.timeout
        elif result == ATOMS.timeout and attempt == 2:
            raise ExecutorTimeoutException()
        else:
            raise ExecutorUnexpectedError(f"Unexpected result: {result}")

    @staticmethod
    def _get_reference():
        rand_val = int(time.monotonic() * 1000000) + random.randrange(1000000)
        rand_bytes = rand_val.to_bytes(length=12,
                                       byteorder="big",
                                       signed=False)
        return Reference(PYTHON_REGISTERED_NAME, 1, rand_bytes)

    async def _send_cmd(self, cmd, counter, reference):
        msg = (
            ATOMS.execute_command,
            self._cmd_receiver.pid_,
            reference,
            counter,
            True,
            cmd.encode("utf-8"),
            self._cmd_receiver.pid_)

        await self._node.send(sender=self._event_receiver.pid_,
                            receiver=(self._atomized_executor_node, ATOMIZED_EXECUTOR_REGISTERED_NAME),
                            message=msg)

    async def _send_event_sink(self):
        await self._node.send(sender=self._event_receiver.pid_,
                              receiver=(self._atomized_executor_node, ATOMIZED_EXECUTOR_REGISTERED_NAME),
                              message=(ATOMS.event_sink, self._event_receiver.pid_))

    @staticmethod
    def _is_dry_run():
        try:
            current_context = CusExecutor._get_robot_context()
            if current_context.dry_run:
                return True
        except Exception:  # nopep8
            pass
        return False

    @staticmethod
    def _get_robot_context():
        try:
            from robot.running.context import EXECUTION_CONTEXTS
            return EXECUTION_CONTEXTS.current
        except Exception:  # nopep8
            pass
        return None

class ExecutorTimeoutException(Exception):
    """Raised when the executor command times out."""
    pass

class ExecutorErrorException(Exception):
    """Raised when the executor returns an error."""
    pass

class ExecutorUnexpectedError(Exception):
    """Raised when the executor returns an unexpected result."""
    pass
